// Normalize demo payload that has shape: { items: [ ... ] }
// Add silent/source/demo_batch/trace_id to EACH inner item.

const run_ts = new Date().toISOString();
const root = items[0]?.json ?? {};

const demo_batch = root.demo_batch ?? run_ts;
const kb_ref  = root.kb_ref ?? "ceo_x_demo";
const chat_id = root.chat_id ?? root.tg_chat_id ?? 0;
const user_id = root.user_id ?? root.tg_user_id ?? 0;

const trace_base =
  root.trace_id ??
  `demo_${kb_ref}_${chat_id}_${user_id}_${demo_batch.replace(/[^0-9]/g, "").slice(0, 14)}`;

const arr = Array.isArray(root.items) ? root.items : [];

const normalized = arr.map((it, idx) => ({
  ...it,
  silent: true,
  source: "demo",
  demo_batch,
  trace_id: `${trace_base}_${String(idx + 1).padStart(2, "0")}`,
}));

return [{
  json: {
    ...root,
    items: normalized,
  }
}];
